description:
Implement `asyncRetry(fn, maxAttempts)` that calls an async function and retries up to `maxAttempts` times on failure. Returns the first successful result, or throws the last error if all attempts fail.

**Example:**
```js
let tries = 0;
const result = await asyncRetry(async () => {
  if (++tries < 3) throw new Error('fail');
  return 'ok';
}, 3);
// result === 'ok'
```

starter_code:
export async function asyncRetry(fn, maxAttempts) {
  // your code here
}

test_suite:
test('returns result on first success', async () => {
  const fn = vi.fn().mockResolvedValue('done');
  const result = await asyncRetry(fn, 3);
  expect(result).toBe('done');
  expect(fn).toHaveBeenCalledTimes(1);
});

test('retries on failure and returns on eventual success', async () => {
  let count = 0;
  const fn = async () => {
    if (++count < 3) throw new Error('not yet');
    return 'ok';
  };
  const result = await asyncRetry(fn, 3);
  expect(result).toBe('ok');
  expect(count).toBe(3);
});

test('throws last error after max attempts', async () => {
  const fn = vi.fn().mockRejectedValue(new Error('fail'));
  await expect(asyncRetry(fn, 3)).rejects.toThrow('fail');
  expect(fn).toHaveBeenCalledTimes(3);
});

// __hidden__
test('maxAttempts of 1 does not retry', async () => {
  const fn = vi.fn().mockRejectedValue(new Error('only once'));
  await expect(asyncRetry(fn, 1)).rejects.toThrow('only once');
  expect(fn).toHaveBeenCalledTimes(1);
});

solution:
export async function asyncRetry(fn, maxAttempts) {
  let lastError;
  for (let i = 0; i < maxAttempts; i++) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}
